// display-only: boxes become components
// [Header] [SearchBar] [ResultList → ResultCard × 3]
function App() {
  return (
    <div>
      <Header />
      <SearchBar />
      <ResultList />
    </div>
  );
}

// display-only: single responsibility
function SearchBar({ query, onQueryChange }) {
  return (
    <input
      value={query}
      onChange={(e) => onQueryChange(e.target.value)}
    />
  );
}
// it searches. that's it. nothing else.

// display-only: data flows down
function App() {
  const user = { name: 'Roli' };
  return <Profile user={user} />; // parent → child
}
function Profile({ user }) {
  return <h1>{user.name}</h1>; // child reads it
}

// display-only: callbacks flow up
function App() {
  const [items, setItems] = useState([]);
  return <AddItem onAdd={(text) => setItems([...items, text])} />;
}
function AddItem({ onAdd }) {
  return <button onClick={() => onAdd('new')}>Add</button>;
}

// display-only: lifting state up
function App() {
  const [query, setQuery] = useState(''); // owned by the parent
  return (
    <div>
      <SearchBar query={query} onQueryChange={setQuery} />
      <ResultList query={query} />
    </div>
  );
}

// display-only: from repetition to component
const users = [{ name: 'Roli' }, { name: 'Ada' }];
return (
  <div>
    {users.map((u) => (
      <UserCard key={u.name} name={u.name} />
    ))}
  </div>
);

